// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GiftCodeBatch) predicate.GiftCodeBatch {
	return predicate.GiftCodeBatch(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
